"""Prepare private, consumed clock-context handoffs; no project imports/execution."""
from pathlib import Path
P=Path(__file__).resolve().parent/'implementation01/project/hms'
def edit(name,changes):
 p=P/name;s=p.read_text()
 for before,after,count in changes:
  assert s.count(before)==count,(name,before,s.count(before),count)
  s=s.replace(before,after)
 p.write_text(s)
